import sys

INF = 1000000

def compute(idx, pCount, nCount, carryVal):
    trueCarry = carryVal - 50
    if idx == 17:
        if pCount + nCount + trueCarry == 0:
            return 0
        else:
            return INF
    if memo[idx][pCount][nCount][carryVal] != -1:
        return memo[idx][pCount][nCount][carryVal]
    minRes = INF
    for p in range(min(16, pCount + 1)):
        for n in range(min(16, nCount + 1)):
            sum_val = pCount - nCount + trueCarry
            digit = (sum_val % 10 + 10) % 10
            nextCarry = (sum_val // 10) if sum_val > 0 else ((sum_val - 9) // 10)
            if digit != int(numStr[idx]):
                continue
            res = compute(idx + 1, pCount - p, nCount - n, nextCarry + 50) + (p + n) * (idx + 1)
            if res < minRes:
                minRes = res
    memo[idx][pCount][nCount][carryVal] = minRes
    return minRes

def main():
    numberInput = int(sys.stdin.read().strip())
    maxSize = 50
    global memo, numStr
    memo = [[[[-1 for _ in range(100)] for _ in range(maxSize)] for _ in range(maxSize)] for _ in range(20)]
    numStr = str(numberInput)
    while len(numStr) < 17:
        numStr = "0" + numStr
    numStr = numStr[::-1]
    answer = INF
    for p in range(maxSize):
        for n in range(maxSize):
            answer = min(answer, compute(0, p, n, 50))
    print(answer)

if __name__ == "__main__":
    main()

